.strategy-card{background:linear-gradient(135deg,#083f76,#0873ce);color:#fff;border:0}.strategy-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px}.strategy-mini{background:#ffffff16;border-radius:12px;padding:10px}.strategy-mini strong{display:block;font-size:1.05rem}.strategy-mini span{display:block;font-size:.58rem;color:#dceeff;margin-top:3px}.strategy-copy{font-size:.72rem;line-height:1.5;color:#e8f4ff;margin-top:10px}
.meta-progress-card{padding:14px 15px}.meta-progress-head{display:flex;align-items:flex-end;justify-content:space-between;gap:12px}.meta-progress-head b{display:block;font-size:.78rem;color:#0b426f}.meta-progress-head small{display:block;margin-top:3px;font-size:.6rem;color:#7e91a5}.meta-progress-head strong{font-size:1.15rem;color:#075cae}.meta-progress-track{height:13px;margin-top:10px;border-radius:99px;background:#e7eef5;overflow:hidden}.meta-progress-fill{height:100%;border-radius:99px;background:linear-gradient(90deg,#13a45a,#50cc82);transition:width .45s ease}
.leader-card{position:relative;overflow:hidden;text-align:center;background:linear-gradient(145deg,#fff8dc,#fff);border:1px solid #f1d479;border-radius:22px;padding:20px 15px;margin-bottom:12px;box-shadow:0 12px 30px #765c1514}.leader-card::before{content:"";position:absolute;inset:-80% auto auto -20%;width:70%;height:220%;background:linear-gradient(90deg,transparent,#ffffffaa,transparent);transform:rotate(18deg)}.leader-card.animate{animation:leaderPop .72s cubic-bezier(.2,.9,.2,1)}.leader-card.animate::before{animation:leaderShine 1.15s ease-out}.leader-crown{font-size:1.55rem}.leader-photo{width:108px;height:108px;border-radius:50%;overflow:hidden;background:#eaf4ff;color:#075cae;display:grid;place-items:center;font-size:1.9rem;font-weight:950;margin:6px auto 10px;border:5px solid #fff;box-shadow:0 0 0 4px #f3cc59,0 10px 25px #23415f28}.leader-photo img{width:100%;height:100%;object-fit:cover}.leader-name{font-size:1.18rem;font-weight:950;color:#0b426f}.leader-stats{margin-top:6px;font-size:.68rem;color:#6d7e8e}.leader-score{display:inline-block;margin-top:10px;padding:7px 12px;border-radius:999px;background:#fff2b8;color:#7e5b00;font-size:.72rem;font-weight:950}
.rank-list-title{font-size:.72rem;font-weight:900;color:#60758a;margin:13px 2px 8px}.rank-empty{font-size:.72rem;color:#7e91a5;text-align:center;padding:18px}
.reacts button{cursor:pointer;transition:transform .12s ease,background .12s ease,box-shadow .12s ease}.reacts button:active{transform:scale(.91)}.reacts button.me{box-shadow:inset 0 0 0 1px #b7d9f7}.reacts button.reacting{opacity:.68}
@keyframes leaderPop{0%{opacity:.2;transform:translateY(16px) scale(.96)}65%{transform:translateY(-3px) scale(1.015)}100%{opacity:1;transform:none}}@keyframes leaderShine{0%{transform:translateX(-160%) rotate(18deg)}100%{transform:translateX(340%) rotate(18deg)}}
@media(max-width:680px){.director-kpis{grid-template-columns:1fr 1fr}.strategy-grid{grid-template-columns:1fr}.period-switch{width:100%}.period-switch button{flex:1}.leader-photo{width:94px;height:94px}}

/* V3.5.4.7 - notificações pessoais */
.arena-notifs{position:relative}.notif-bell{width:38px;height:38px;min-width:38px;border:1px solid #ffffff30;border-radius:10px;background:#ffffff16;color:#fff;display:grid;place-items:center;cursor:pointer;position:relative}.notif-bell:hover{background:#ffffff25}.notif-badge{display:none;position:absolute;right:-5px;top:-5px;min-width:18px;height:18px;padding:0 4px;border-radius:99px;background:#ef4444;color:#fff;border:2px solid #0b69bd;font-size:.55rem;font-weight:950;place-items:center}.notif-badge.on{display:grid}.notif-menu{display:none;position:absolute;right:0;top:46px;width:min(390px,92vw);max-height:520px;overflow:auto;background:#fff;color:#183b59;border:1px solid #d9e5ef;border-radius:16px;box-shadow:0 22px 60px #001b3650;z-index:1000}.notif-menu.on{display:block}.notif-head{position:sticky;top:0;background:#fff;padding:12px 14px;border-bottom:1px solid #edf2f6;font-size:.75rem;font-weight:950;z-index:2}.notif-empty{padding:20px 14px;text-align:center;color:#8aa0b4;font-size:.7rem}.notif-item{width:100%;border:0;border-bottom:1px solid #eef3f7;background:#fff;padding:11px 13px;text-align:left;cursor:pointer;display:grid;grid-template-columns:34px 1fr;gap:9px}.notif-item:hover{background:#f7fbff}.notif-item.unread{background:#eef7ff}.notif-ico{width:34px;height:34px;border-radius:10px;background:#eaf4ff;display:grid;place-items:center;font-size:.95rem}.notif-copy b{display:block;font-size:.69rem;color:#183b59}.notif-copy p{margin:3px 0 0;color:#657d93;font-size:.62rem;line-height:1.35}.notif-copy small{display:block;margin-top:4px;color:#9aabbb;font-size:.55rem}

/* V3.5.4.6 - carregamento guiado */
.arena-loading{position:fixed;inset:0;z-index:99999;background:linear-gradient(145deg,#075cae,#063d77);display:flex;align-items:center;justify-content:center;padding:24px;color:#fff;transition:opacity .28s ease,visibility .28s ease}
.arena-loading.off{opacity:0;visibility:hidden;pointer-events:none}
.arena-loading-card{width:min(460px,92vw);text-align:center}
.arena-loading-logo{height:58px;max-width:220px;object-fit:contain;margin-bottom:24px;filter:drop-shadow(0 4px 12px #0003)}
.arena-spinner{width:58px;height:58px;border:5px solid #ffffff33;border-top-color:#fff;border-radius:50%;margin:0 auto 20px;animation:arenaSpin .9s linear infinite}
.arena-loading-title{font-size:1.15rem;font-weight:950;margin-bottom:7px}.arena-loading-text{font-size:.82rem;color:#d9eaff;min-height:22px}.arena-loading-dots{display:flex;gap:6px;justify-content:center;margin-top:18px}.arena-loading-dots i{width:7px;height:7px;border-radius:50%;background:#ffffff55}.arena-loading-dots i.on{background:#fff;transform:scale(1.2)}
@keyframes arenaSpin{to{transform:rotate(360deg)}}
.meta-config-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-top:8px}.meta-config-grid label{font-size:.62rem;color:var(--mut);font-weight:800;display:block}.meta-config-grid input{margin-top:4px}.meta-config-help{font-size:.64rem;color:#647b91;line-height:1.45;margin:8px 2px 10px}.meta-calendar-badge{display:inline-flex;gap:6px;align-items:center;background:#eaf4ff;color:#075cae;border-radius:999px;padding:5px 8px;font-size:.62rem;font-weight:900;margin-top:6px}
@media(max-width:640px){.meta-config-grid{grid-template-columns:1fr}}

/* v3.5.4.8 - Meu Painel: KPI individual + comissão + acompanhamento */
.my-kpi-progress{background:#fff;border:1px solid var(--line);border-radius:17px;padding:15px;margin-bottom:10px}.my-kpi-progress-head{display:flex;align-items:flex-end;justify-content:space-between;gap:10px}.my-kpi-progress-head b{font-size:.82rem}.my-kpi-progress-head strong{font-size:1.35rem;color:#075cae}.my-progress-track{height:13px;background:#e7eef5;border-radius:999px;overflow:hidden;margin-top:10px}.my-progress-fill{height:100%;background:linear-gradient(90deg,#17a85b,#55cf87);border-radius:999px;transition:width .6s ease}.my-kpi-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-bottom:10px}.my-kpi{background:#fff;border:1px solid var(--line);border-radius:15px;padding:13px}.my-kpi strong{display:block;font-size:1.18rem;color:#0b426f}.my-kpi span{display:block;margin-top:4px;font-size:.61rem;color:var(--mut)}.my-kpi small{display:block;margin-top:4px;font-size:.57rem;color:#60758a;line-height:1.35}.my-strategy{background:linear-gradient(135deg,#083f76,#0873ce);color:#fff;border:0}.my-strategy b{font-size:.86rem}.my-strategy p{font-size:.7rem;line-height:1.55;color:#e4f2ff;margin:8px 0 0}.commission-card{background:linear-gradient(135deg,#102c4a,#075cae);color:#fff;border:0}.commission-head{display:flex;align-items:center;gap:10px}.commission-head>div:first-child{flex:1}.commission-state{padding:5px 9px;border-radius:999px;background:#ffffff20;font-size:.6rem;font-weight:950}.commission-state.on{background:#d9fbe8;color:#08783d}.commission-money{font-size:1.65rem;font-weight:1000;margin-top:10px}.commission-sub{font-size:.65rem;color:#d8eaff;margin-top:3px}.commission-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:10px}.commission-mini{background:#ffffff14;border-radius:12px;padding:9px}.commission-mini strong{display:block;font-size:.95rem}.commission-mini span{display:block;margin-top:3px;font-size:.56rem;color:#d8eaff}.commission-track{height:8px;background:#ffffff22;border-radius:99px;overflow:hidden;margin-top:10px}.commission-track>div{height:100%;background:#50df92;border-radius:99px}.feedback-card{border-left:4px solid #8b5cf6}.feedback-card b{font-size:.82rem}.feedback-card p{font-size:.72rem;line-height:1.55;color:#536a80;margin:8px 0 0}.feedback-date{font-size:.58rem;color:#8b9bad;margin-top:8px}@media(min-width:760px){.my-kpi-grid{grid-template-columns:repeat(4,1fr)}}


/* v3.5.6.2 - fila pessoal de atendimentos */
.att-queue{display:grid;gap:9px;margin-bottom:14px}.att-card{background:#fff;border:1px solid #dce8f3;border-radius:14px;padding:13px;box-shadow:0 5px 18px #153b5b0b}.att-card.live{border-color:#7fc5ff;background:linear-gradient(135deg,#f5fbff,#fff)}.att-head{display:flex;justify-content:space-between;gap:8px;align-items:flex-start}.att-head b{font-size:.82rem;color:#173f60}.att-chip{font-size:.57rem;font-weight:950;border-radius:999px;padding:5px 8px;background:#eef5fb;color:#51708b}.att-chip.live{background:#dcfce7;color:#166534}.att-meta{font-size:.62rem;color:#71869a;margin-top:5px;line-height:1.45}.att-actions{display:flex;gap:7px;margin-top:10px;flex-wrap:wrap}.att-actions button{border:0;border-radius:9px;padding:8px 10px;font-weight:900;font-size:.62rem;cursor:pointer}.att-start{background:#0873ce;color:#fff}.att-finish{background:#173f60;color:#fff}.att-empty{padding:16px;text-align:center;color:#71869a}.att-modal{position:fixed;inset:0;background:#10283c66;z-index:10010;display:none;align-items:center;justify-content:center;padding:16px}.att-modal.on{display:flex}.att-box{width:min(520px,100%);background:#fff;border-radius:18px;padding:18px;box-shadow:0 22px 70px #10283c55}.att-box h3{margin:0 0 5px;color:#173f60}.att-box p{font-size:.65rem;color:#71869a}.att-box label{display:block;font-size:.62rem;font-weight:900;color:#49667f;margin-top:11px}.att-box select,.att-box textarea{width:100%;box-sizing:border-box;margin-top:5px;border:1px solid #d6e3ee;border-radius:10px;padding:10px;font:inherit}.att-box textarea{min-height:84px;resize:vertical}.att-modal-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:14px}.att-modal-actions button{border:0;border-radius:10px;padding:9px 12px;font-weight:900;cursor:pointer}.att-save{background:#0873ce;color:#fff}.att-cancel{background:#edf3f8;color:#49667f}.att-note{margin-top:9px;padding:9px;border-radius:9px;background:#fff8e6;color:#7a5a10;font-size:.6rem;line-height:1.4}

/* v3.9.0 TESTE - Arena RPG: camada visual, sem alterar banco */
.rpg-shell{background:radial-gradient(circle at 85% 0,#274a8a 0,#10294d 35%,#07192f 100%);border:1px solid #315785;border-radius:22px;padding:15px;color:#fff;box-shadow:0 18px 45px #061a3030;margin-bottom:12px;overflow:hidden;position:relative}.rpg-shell:after{content:"";position:absolute;width:190px;height:190px;border-radius:50%;right:-80px;top:-100px;background:#ffffff0a;pointer-events:none}.rpg-head{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:12px}.rpg-head b{font-size:.88rem}.rpg-head span{font-size:.56rem;font-weight:950;padding:5px 8px;border-radius:999px;background:#ffffff17;color:#d9eaff}.rpg-party{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.rpg-hero{background:#ffffff0d;border:1px solid #ffffff18;border-radius:16px;padding:10px;text-align:center;position:relative}.rpg-avatar{width:58px;height:58px;border-radius:50%;margin:0 auto 7px;display:grid;place-items:center;font-size:1.65rem;background:linear-gradient(145deg,#2d78d0,#173e74);border:3px solid #ffffffcc;box-shadow:0 0 0 3px #5fa9ff44}.rpg-avatar img{width:100%;height:100%;object-fit:cover;border-radius:50%}.rpg-level{position:absolute;right:7px;top:7px;background:#ffd35a;color:#503900;border-radius:999px;padding:3px 6px;font-size:.5rem;font-weight:1000}.rpg-hero strong{display:block;font-size:.68rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.rpg-hero small{display:block;color:#b9d3ef;font-size:.52rem;margin-top:2px}.rpg-xp{height:5px;background:#ffffff20;border-radius:99px;overflow:hidden;margin-top:7px}.rpg-xp i{display:block;height:100%;background:linear-gradient(90deg,#50e39b,#b8ff78);border-radius:99px}.boss-card{margin-top:10px;background:linear-gradient(135deg,#4c1630,#7d233d);border:1px solid #ff779d55;border-radius:17px;padding:12px}.boss-top{display:flex;align-items:center;gap:10px}.boss-icon{font-size:2rem}.boss-top div{flex:1}.boss-top b{font-size:.76rem}.boss-top small{display:block;color:#ffd5e1;font-size:.55rem;margin-top:2px}.boss-hp{height:13px;background:#2d0d1c;border-radius:99px;overflow:hidden;margin-top:9px;border:1px solid #ffffff20}.boss-hp i{display:block;height:100%;background:linear-gradient(90deg,#ff3e72,#ff9a55);transition:width .6s ease}.boss-foot{display:flex;justify-content:space-between;margin-top:6px;font-size:.55rem;color:#ffd5e1}.rpg-duel{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:8px;margin-top:10px}.rpg-fighter{text-align:center}.rpg-fighter .rpg-avatar{width:52px;height:52px;font-size:1.35rem}.rpg-fighter b{display:block;font-size:.62rem}.rpg-vs{font-size:.75rem;font-weight:1000;color:#ffd35a}.rpg-hp{height:7px;background:#ffffff20;border-radius:99px;overflow:hidden;margin-top:5px}.rpg-hp i{display:block;height:100%;background:#5ee09a}.rpg-hp.enemy i{background:#ff6684}.rpg-caption{font-size:.55rem;color:#b9d3ef;text-align:center;margin-top:8px;line-height:1.4}@media(max-width:640px){.rpg-party{grid-template-columns:repeat(3,minmax(0,1fr))}.rpg-hero{padding:8px 5px}.rpg-avatar{width:48px;height:48px}.rpg-hero small{display:none}}
</style></head><body>
<div id="arenaLoading" class="arena-loading"><div class="arena-loading-card"><img class="arena-loading-logo" src="../logo-liceu.png" alt="Liceu Brasil"><div class="arena-spinner"></div><div class="arena-loading-title">Preparando a Arena</div><div id="arenaLoadingText" class="arena-loading-text">Conectando aos dados comerciais...</div><div class="arena-loading-dots" id="arenaLoadingDots"><i class="on"></i><i></i><i></i><i></i><i></i></div></div></div>
<header class="top"><div class="toprow"><div class="logo"><img class="arena-brand-logo" src="../logo-liceu.png" alt="Liceu Brasil"></div><div class="live" id="who">Carregando...</div><div class="arena-notifs"><button id="notifBell" class="notif-bell" type="button" onclick="toggleNotifications(event)" title="Notificações"><i class="fa-solid fa-bell"></i><span id="notifBadge" class="notif-badge">0</span></button><div id="notifMenu" class="notif-menu"><div class="notif-head">🔔 Suas notificações</div><div id="notifList" class="notif-empty">Carregando...</div></div></div><button class="logout-top" type="button" onclick="logout()" title="Sair"><i class="fa-solid fa-arrow-right-from-bracket"></i></button></div></header>
<main class="wrap">
<section id="timeline" class="view on"><div class="card"><div class="livebar"><div class="mini"><strong id="ag">0</strong><span>agendamentos</span></div><div class="mini"><strong id="vis">0</strong><span>visitas hoje</span></div><div class="mini"><strong id="mat">0</strong><span>matrículas</span></div></div></div><div class="card composer-card"><div class="composer-row"><textarea id="postText" maxlength="280" placeholder="Compartilhe uma atualização com a equipe..."></textarea><button class="primary" type="button" onclick="publishPost()"><i class="fa-solid fa-paper-plane"></i> Publicar</button></div><div class="composer-meta"><span>Mensagem curta para a Timeline</span><b id="postCount">0/280</b></div></div><div class="sectiontitle">🎮 Arena RPG <span style="font-size:.55rem;color:#7e91a5">• versão de teste</span></div><div id="arenaRpg"></div><div class="sectiontitle">⚔️ Desafios de hoje</div><div id="challengeList"></div><div class="sectiontitle">Ao vivo</div><div id="feed"></div></section>
<section id="performance" class="view">
<div class="sectiontitle">📊 Painel da equipe</div>
<div class="period-switch" id="rankingPeriodSwitch"><button type="button" class="on" data-p="dia" onclick="setRankingPeriodo('dia',this)">Hoje</button><button type="button" data-p="semana" onclick="setRankingPeriodo('semana',this)">Semana</button><button type="button" data-p="mes" onclick="setRankingPeriodo('mes',this)">Mês</button></div>
<div id="directorPerformance" class="hide"></div>
<div class="sectiontitle" id="rankingTitle">🏆 Ranking de hoje</div>
<div id="leaderSpotlight"></div>
<div id="ranking"></div>
</section>
<section id="mine" class="view"><div class="sectiontitle">Meu acompanhamento</div><div id="myPanel"><div class="card">Carregando seus resultados...</div></div></section>
<section id="attend" class="view"><div class="sectiontitle">🧑‍💼 Meus atendimentos</div><div class="card" style="margin-bottom:9px"><b>Sua fila de atendimento</b><div style="font-size:.65rem;color:#71869a;margin-top:5px;line-height:1.45">As visitas encaminhadas para você aparecem aqui. Inicie o atendimento e registre o resultado quando concluir.</div></div><div id="attendancePageQueue" class="att-queue"><div class="card att-empty">Carregando seus atendimentos...</div></div></section>
<section id="team" class="view"><div id="betPanel" class="hide"></div><div class="sectiontitle">Equipe</div><div id="teamList"></div></section>
<section id="config" class="view"><div id="managerConfig"><div class="card"><b>Configuração da meta</b><div class="meta-config-grid"><label>Início da meta<input id="metaInicio" type="date"></label><label>Meta de matrículas<input id="meta" type="number" min="1" placeholder="Ex.: 500"></label><label>Dias comerciais da meta<input id="dias" type="number" min="1" placeholder="Ex.: 26"></label></div><div class="meta-config-help">A Arena conta como dia comercial de <b>segunda a sábado</b>. Domingo não entra no ritmo, nas médias nem nos dias decorridos.</div><div id="metaCalendarInfo" class="meta-calendar-badge">📅 Carregando período...</div><div style="margin-top:10px"><button class="primary" onclick="saveConfig()">Salvar meta</button></div></div></div>
<div id="masterRecoveryPanel" class="hide"><div class="card" style="border:1px solid #f2c45c;background:linear-gradient(135deg,#fffaf0,#fff)"><b style="color:#8a5b00">👑 Recuperar Diretor Master</b><div style="font-size:.64rem;color:#6f7f8e;line-height:1.5;margin-top:6px">Ainda não existe Diretor Master definido. Como este acesso é de Diretoria e você também está autenticado como Administrador no sistema principal, pode assumir a titularidade inicial. Depois disso, o Master fica travado e não pode ser transferido pela interface.</div><button class="primary" type="button" style="margin-top:10px;background:#b77900" onclick="recoverMaster()"><i class="fa-solid fa-crown"></i> Tornar este acesso Diretor Master</button></div></div>
<div id="adminUsersPanel" class="hide">
<div class="card"><div class="user-form-title"><b id="userFormTitle">Novo acesso da Arena</b><span style="font-size:.62rem;color:#0873ce;font-weight:900">DIRETOR MASTER</span></div><input id="uid" type="hidden"><input id="unome" placeholder="Nome"><input id="uuser" placeholder="Usuário"><input id="upass" type="password" placeholder="Senha (mínimo 6 caracteres)"><select id="uperfil"><option value="vendedor">Vendedor</option><option value="gestor">Gestor</option><option value="diretoria">Diretoria</option><option value="financeiro">Financeiro</option></select><select id="uvend"><option value="">Sem vínculo com vendedor</option></select><div class="user-photo-box"><div id="userPhotoPreview" class="user-photo-preview">👤</div><div><div style="font-size:.68rem;font-weight:900;margin-bottom:6px">Foto do usuário</div><div class="user-photo-tools"><label class="photo-pick"><i class="fa-solid fa-camera"></i> Escolher foto<input id="ufoto" type="file" accept="image/*" style="display:none" onchange="prepareArenaUserPhoto(this.files?.[0])"></label><button class="photo-remove" type="button" onclick="removeArenaUserPhoto()">Remover</button></div><div style="font-size:.56rem;color:#8a9aac;margin-top:5px">Usada em comentários e publicações de Diretoria/Gestão sem vínculo com vendedor.</div></div></div><label class="active-row"><input id="uativo" type="checkbox" checked> Acesso ativo</label><div class="admin-only-note" id="passwordHint">Ao criar um acesso, informe uma senha com pelo menos 6 caracteres.</div><div class="user-form-actions"><button class="primary" id="userSaveBtn" onclick="saveUser()">Criar acesso</button><button class="secondary-btn hide" id="userCancelBtn" onclick="cancelEditUser()">Cancelar edição</button></div></div>
<div class="sectiontitle">🔐 Acessos cadastrados</div><div id="userList" class="admin-users"><div class="card">Carregando acessos...</div></div></div>
<div class="card"><button class="primary" onclick="logout()">Sair da Arena</button></div></section>
</main>
<nav class="nav"><div class="navin" style="grid-template-columns:repeat(5,1fr)"><button class="on" data-v="timeline"><i class="fa-solid fa-bolt"></i>Timeline</button><button data-v="performance"><i class="fa-solid fa-chart-line"></i>Equipe</button><button data-v="mine"><i class="fa-solid fa-chart-column"></i>Meu painel</button><button data-v="team"><i class="fa-solid fa-users"></i>Time</button><button id="navConfigAttendance" data-v="config"><i class="fa-solid fa-gear"></i>Config</button></div></nav>
<div id="tutorial" class="tutorial"><div class="tutorial-card"><div id="tutorialStep" class="tutorial-step"></div><h2 id="tutorialTitle"></h2><p id="tutorialText"></p><div class="tutorial-actions"><button class="tutorial-skip" onclick="finishTutorial()">Pular</button><button class="tutorial-next" onclick="nextTutorial()">Próximo</button></div></div></div>
<div id="reactionModal" class="reaction-modal" onclick="if(event.target===this)closeReactionModal()"><div class="reaction-box"><div class="reaction-box-head"><b id="reactionTitle">Reações</b><button class="reaction-close" type="button" onclick="closeReactionModal()">×</button></div><div id="reactionPeople"></div></div></div>
<div id="profileModal" class="profile-modal" onclick="if(event.target===this)closeProfile()"><div class="profile-shell" id="profileShell"><div class="profile-cover"><button class="profile-close" type="button" onclick="closeProfile()">×</button><div id="profileContent">Carregando perfil...</div></div></div></div>

<div id="contractDetailModal" class="contract-modal" onclick="if(event.target===this)closeContractDetail()"><div class="contract-box"><div class="contract-head"><div><h3 id="contractDetailTitle" style="margin:0;color:#075cae">Detalhes do contrato</h3><div id="contractDetailMeta" style="font-size:.65rem;color:#7e91a5;margin-top:5px"></div></div><button class="contract-close" type="button" onclick="closeContractDetail()">×</button></div><div id="contractDetailBody"></div></div></div>

<div id="betModal" class="bet-modal" onclick="if(event.target===this)closeBetModal()"><div class="bet-box"><div style="display:flex;align-items:flex-start;gap:10px"><div style="flex:1"><h3 style="margin:0;color:#6b3ea2">🎰 Aposta de confiança</h3><p id="betTarget" style="font-size:.68rem;color:#71869a;margin:5px 0 10px">Vendedor</p></div><button class="contract-close" type="button" onclick="closeBetModal()">×</button></div><label>Desafio<select id="betType"><option value="proxima_matricula">Fecha a próxima matrícula</option><option value="duas_matriculas">Chega a 2 matrículas hoje</option><option value="hat_trick">Faz um HAT-TRICK hoje</option></select></label><label>Fichas<input id="betChips" type="number" min="1" max="100" value="25"></label><div id="betSaldoInfo" style="font-size:.62rem;color:#71869a"></div><div style="font-size:.58rem;color:#8a9aac;margin-top:7px">Fichas virtuais da Arena, sem valor financeiro e sem resgate em dinheiro.</div><div class="bet-actions"><button type="button" style="background:#eef2f7;color:#64748b" onclick="closeBetModal()">Cancelar</button><button type="button" style="background:#6b3ea2;color:#fff" onclick="saveBet()">Apostar fichas</button></div></div></div>
<div id="attendanceModal" class="att-modal" onclick="if(event.target===this)closeAttendanceModal()"><div class="att-box"><h3>Finalizar atendimento</h3><p id="attendanceClient">Cliente</p><label>Resultado<select id="attendanceResult" onchange="toggleAttendanceFields()"><option value="">Selecione...</option><option value="Gratuito">Curso gratuito</option><option value="Sem Interesse">Sem interesse</option><option value="Retorno">Retorno</option></select></label><div id="attendanceFreeBox" style="display:none"><label>Curso / turma gratuita<select id="attendanceAgenda"><option value="">Selecione a turma...</option></select></label></div><label>Observações<textarea id="attendanceObs" maxlength="700" placeholder="Registre o que aconteceu no atendimento, objeções, retorno combinado etc."></textarea></label><div class="att-note">Nesta primeira versão de teste, matrícula paga continua sendo concluída pelo fluxo completo do Controle de Visitas, porque exige contrato, plano financeiro e situação da taxa.</div><div class="att-modal-actions"><button class="att-cancel" type="button" onclick="closeAttendanceModal()">Cancelar</button><button class="att-save" type="button" onclick="saveAttendanceResult()">Finalizar</button></div></div></div>
<script>
const ARENA_CSRF_TOKEN = <?= json_encode(authCsrfToken(), JSON_UNESCAPED_SLASHES) ?>;
const $=s=>document.querySelector(s);let S=null;let MY=null;let ATEND=null;let ATT_CURRENT=null;let ARENA_USERS=[];let ARENA_CURRENT_USER_ID=0;
let arenaInitialLoad=true,arenaLoadingTimer=null,arenaLoadingStep=0;
const arenaLoadingMessages=['Conectando aos dados comerciais...','Atualizando atendimentos e visitas...','Contabilizando as matrículas...','Calculando ritmo e meta da equipe...','Montando ranking e indicadores...'];
function startArenaLoading(){const box=document.getElementById('arenaLoading'),txt=document.getElementById('arenaLoadingText');if(!box)return;box.classList.remove('off');arenaLoadingStep=0;if(txt)txt.textContent=arenaLoadingMessages[0];clearInterval(arenaLoadingTimer);arenaLoadingTimer=setInterval(()=>{arenaLoadingStep=Math.min(arenaLoadingStep+1,arenaLoadingMessages.length-1);if(txt)txt.textContent=arenaLoadingMessages[arenaLoadingStep];document.querySelectorAll('#arenaLoadingDots i').forEach((d,i)=>d.classList.toggle('on',i===arenaLoadingStep));},850)}
function stopArenaLoading(){clearInterval(arenaLoadingTimer);const txt=document.getElementById('arenaLoadingText');if(txt)txt.textContent='Tudo pronto!';setTimeout(()=>document.getElementById('arenaLoading')?.classList.add('off'),260)}
startArenaLoading();
async function api(a,m='GET',b=null,p={}){let q=new URLSearchParams({action:a,...p});let r=await fetch('api.php?'+q,{method:m,credentials:'same-origin',headers:b?{'Content-Type':'application/json','X-CSRF-Token':ARENA_CSRF_TOKEN}:{'Accept':'application/json'},body:b?JSON.stringify(b):null,cache:'no-store'});let j=await r.json();if(r.status===401){location='arena-login.php';throw Error('login')}if(!r.ok||j.ok===false)throw Error(j.error||'Erro');return j}
const esc=x=>{let d=document.createElement('div');d.textContent=x??'';return d.innerHTML}, pct=x=>(x==null?'—':x+'%');
const initials=n=>String(n||'V').trim().split(/\s+/).slice(0,2).map(p=>p[0]||'').join('').toUpperCase();
function photoHtml(nome,foto,cls='photo'){return foto?`<div class="${cls}"><img src="${esc(foto)}" alt="${esc(nome)}"></div>`:`<div class="${cls}">${esc(initials(nome))}</div>`;}
function icon(t){return {matricula:'fa-trophy',atendimento:'fa-headset',sem_interesse:'fa-arrow-rotate-right',gratuito:'fa-graduation-cap',cutucada:'fa-hand-point-right',desafio:'fa-hand-fist',desafio_resposta:'fa-fire',desafio_resultado:'fa-trophy',ranking_diario:'fa-crown',aposta:'fa-dice',aposta_resultado:'fa-bullseye',post:'fa-quote-left',comentario:'fa-comment'}[t]||'fa-bolt'}
const REACTION_TYPES={curtir:'❤️',palmas:'👏',fogo:'🔥',triste:'😢'};
function reactionData(e,t){return (e.reacoes||[]).find(r=>r.reacao===t)||{qtd:0,meu:0,nomes:[]}}
const reactionPending=new Set();
function reactions(e){return Object.entries(REACTION_TYPES).map(([k,x])=>{const r=reactionData(e,k),key=`${e.id}:${k}`;return `<button type="button" class="${Number(r.meu)===1?'me':''} ${reactionPending.has(key)?'reacting':''}" onclick="react(${e.id},'${k}')" title="${r.qtd?esc((r.nomes||[]).join(', ')):'Ninguém reagiu ainda'}">${x} ${r.qtd||0}</button>`}).join('')}
function reactionSummary(e){const partes=Object.entries(REACTION_TYPES).map(([k,emoji])=>{const r=reactionData(e,k), nomes=r.nomes||[];if(!Number(r.qtd||0))return '';let texto=nomes.slice(0,2).join(', ');if(Number(r.qtd)>2)texto+=` e mais ${Number(r.qtd)-2}`;return `<button type="button" onclick="openReactionModal(${e.id},'${k}')">${emoji} ${esc(texto||String(r.qtd))}</button>`}).filter(Boolean);return partes.length?`<div class="reaction-summary">${partes.join(' &nbsp;•&nbsp; ')}</div>`:''}
function openReactionModal(eventId,tipo){const e=(S?.timeline||[]).find(x=>Number(x.id)===Number(eventId));if(!e)return;const r=reactionData(e,tipo), nomes=r.nomes||[];reactionTitle.textContent=`${REACTION_TYPES[tipo]||'✨'} ${r.qtd||0} reação${Number(r.qtd)===1?'':'ões'}`;reactionPeople.innerHTML=nomes.length?nomes.map(n=>`<div class="reaction-person"><span class="reaction-emoji">${REACTION_TYPES[tipo]||'✨'}</span><b>${esc(n)}</b></div>`).join(''):'<div class="reaction-person">Ninguém reagiu ainda.</div>';reactionModal.classList.add('on')}
function closeReactionModal(){reactionModal.classList.remove('on')}
function badgeMini(vendedorId){const r=(S?.ranking||[]).find(x=>Number(x.id)===Number(vendedorId));const b=r?.brasao;if(!b)return '';return `<span class="badge-mini ${esc(b.classe||'')}"><i class="fa-solid ${esc(b.icone||'fa-shield-halved')}"></i>${esc(b.nivel||'')}</span>`}
function commentHtml(c){const avatar=c.foto?`<div class="comment-avatar"><img src="${esc(c.foto)}" alt="${esc(c.nome)}"></div>`:`<div class="comment-avatar">${esc(initials(c.nome))}</div>`;const nome=c.vendedorId?`<b class="profile-link" onclick="openProfile(${Number(c.vendedorId)})">${esc(c.nome)}</b>`:`<b>${esc(c.nome)}</b>`;return `<div class="comment">${avatar}<div>${nome}<p>${esc(c.texto)}</p><small>${esc(c.criadoEm)}</small></div>${c.podeExcluir?`<button class="comment-del" title="Excluir" onclick="deleteComment(${Number(c.id)})"><i class="fa-solid fa-trash-can"></i></button>`:''}</div>`}
function captureFeedDrafts(){const drafts={};document.querySelectorAll('#feed input[id^="comment-"]').forEach(el=>{drafts[el.id]=el.value});const active=document.activeElement;return {drafts,activeId:active?.id?.startsWith('comment-')?active.id:'',start:active?.selectionStart??null,end:active?.selectionEnd??null}}
function restoreFeedDrafts(snap){if(!snap)return;Object.entries(snap.drafts||{}).forEach(([id,value])=>{const el=document.getElementById(id);if(el)el.value=value});if(snap.activeId){const el=document.getElementById(snap.activeId);if(el){el.focus({preventScroll:true});try{if(snap.start!==null)el.setSelectionRange(snap.start,snap.end??snap.start)}catch(_){}}}}
const commentPending=new Set();
function renderFeed(){if(!S)return;const draftSnap=captureFeedDrafts();feed.innerHTML=S.timeline.length?S.timeline.map(e=>{const nome=esc(e.vendedor_nome||'Equipe');const nomeLink=e.vendedor_id?`<span class="profile-link" onclick="openProfile(${Number(e.vendedor_id)})">${nome}</span>${badgeMini(e.vendedor_id)}`:nome;let tituloEvento;if(e.tipo==='cutucada')tituloEvento=esc(e.titulo);else if(e.tipo==='post')tituloEvento=`${nomeLink} publicou`;else tituloEvento=`${nomeLink} ${esc(e.titulo)}`;const comentarios=e.comentarios||[];const ordem=Number(e.dados?.ordem_dia||0);const glory=e.tipo==='matricula'?`<div class="event-glory">${ordem===3?'🔥 HAT-TRICK':esc(e.dados?.gloria||'NOVA MATRÍCULA')}</div>`:(e.tipo==='ranking_diario'?'<div class="event-glory">👑 CAMPEÃO DO DIA</div>':(e.tipo==='aposta'?`<div class="event-glory">🎰 ${e.dados?.todas?'TUDO NA MESA':'APOSTA DE CONFIANÇA'}</div>`:''));const eventClass=e.tipo==='matricula'?` event-matricula ${ordem===3?'hattrick':''}`:(e.tipo==='ranking_diario'?' event-ranking':(e.tipo==='gratuito'?' event-gratuito':(e.tipo==='aposta'||e.tipo==='aposta_resultado'?' event-aposta':'')));const podeAvatar=!!e.vendedor_id || !!e.vendedor_foto;const avatar=podeAvatar?(e.vendedor_id?`<div onclick="openProfile(${Number(e.vendedor_id)})" style="cursor:pointer">${photoHtml(e.vendedor_nome,e.vendedor_foto)}</div>`:photoHtml(e.vendedor_nome,e.vendedor_foto)):`<div class="ico"><i class="fa-solid ${icon(e.tipo)}"></i></div>`;const sending=commentPending.has(Number(e.id));return `<article class="card event${eventClass}">${avatar}<div>${glory}<h3>${tituloEvento}</h3><p>${esc(e.descricao)}</p><span class="time">${esc(e.criado_em)}</span><div class="reacts">${reactions(e)}${e.vendedor_id?`<button class="poke" onclick="poke(${e.vendedor_id})">👉 Cutucar</button>`:''}</div>${reactionSummary(e)}<div class="comment-area"><div class="comment-list">${comentarios.map(commentHtml).join('')}</div><div class="comment-compose ${sending?'sending':''}"><input id="comment-${e.id}" maxlength="220" placeholder="Comentar esta atualização..." autocomplete="off"><button type="button" onclick="addComment(${e.id})" title="Enviar comentário"><i class="fa-solid ${sending?'fa-spinner fa-spin':'fa-paper-plane'}"></i></button></div></div></div></article>`}).join(''):'<div class="card">Nada aconteceu ainda hoje.</div>';restoreFeedDrafts(draftSnap)}
let rankingPeriodoAtual='dia';
function fmtNumero(v,casas=0){const n=Number(v);return Number.isFinite(n)?n.toLocaleString('pt-BR',{minimumFractionDigits:casas,maximumFractionDigits:casas}):'—'}
function setRankingPeriodo(periodo,btn=null){rankingPeriodoAtual=['dia','semana','mes'].includes(periodo)?periodo:'dia';document.querySelectorAll('#rankingPeriodSwitch button').forEach(b=>b.classList.toggle('on',b.dataset.p===rankingPeriodoAtual));renderPerformance(false)}
function leaderPhotoHtml(r){return r?.foto?`<div class="leader-photo"><img src="${esc(r.foto)}" alt="${esc(r.nome)}"></div>`:`<div class="leader-photo">${esc(initials(r?.nome||'V'))}</div>`}
function renderPerformance(animar=false){
 if(!S)return;
 const p=S.periodos?.[rankingPeriodoAtual]||{ranking:S.ranking||[],visitas:0,matriculas:0,conversao:0,indiceMV:0,visitasPorMatricula:null};
 const lista=p.ranking||[], top=lista[0]||null, f=S.funil||{};
 const periodoNome=rankingPeriodoAtual==='dia'?'hoje':rankingPeriodoAtual==='semana'?'da semana':'do mês';
 rankingTitle.textContent=`🏆 Ranking ${periodoNome}`;
 if(S.user.perfil==='diretoria'){
   directorPerformance.classList.remove('hide');
   const progresso=f.meta>0?(Number(f.matriculas||0)/Number(f.meta))*100:0;
   const eficiencia=f.visitasPorMatricula??(Number(f.matriculas||0)>0?Number(f.visitasMes||0)/Number(f.matriculas||0):null);
   const conversaoMeta=Number(f.visitasMes||0)>0?(Number(f.matriculas||0)/Number(f.visitasMes||0))*100:0;
   const ritmoAtual=Number(f.mediaMatriculasDia||0);
   const ritmoIdeal=Number(f.ritmoIdealDia||0);
   const ritmoRecuperacao=Number(f.matriculasDiaRecuperacao||0);
   const deltaRitmo=ritmoAtual-ritmoIdeal;
   const ritmoLabel=deltaRitmo>=0?`${fmtNumero(deltaRitmo,1)} acima da média ideal`:`${fmtNumero(Math.abs(deltaRitmo),1)} abaixo da média ideal`;
   const gapAcumulado=Number(f.gapRitmo||0);
   const gapAcumuladoLabel=gapAcumulado>=0?`${fmtNumero(gapAcumulado,1)} acima do esperado até hoje`:`${fmtNumero(Math.abs(gapAcumulado),1)} abaixo do esperado até hoje`;
   directorPerformance.innerHTML=`<div class="card meta-progress-card">
     <div class="meta-progress-head"><div><b>🎯 Progresso da meta</b><small>${fmtNumero(f.matriculas)} de ${fmtNumero(f.meta)} matrículas • ${fmtNumero(f.diasDecorridos)} dia(s) comercial(is) usados • ${fmtNumero(f.diasRestantes)} restante(s)</small></div><strong>${fmtNumero(progresso,1)}%</strong></div>
     <div class="meta-progress-track"><div class="meta-progress-fill" style="width:${Math.min(100,Math.max(0,progresso))}%"></div></div>
   </div>
   <div class="director-kpis">
     <div class="director-kpi"><strong>${fmtNumero(f.visitasMes)}</strong><span>visitas no período da meta</span><small>${esc(f.metaInicio||'')} → ${esc(f.metaFimBr||'')}</small></div>
     <div class="director-kpi"><strong>${fmtNumero(f.matriculas)}</strong><span>matrículas no período da meta</span><small>${gapAcumuladoLabel}</small></div>
     <div class="director-kpi"><strong>${eficiencia?fmtNumero(eficiencia,1)+' / 1':'—'}</strong><span>visitas ÷ matrículas</span><small>${eficiencia?`1 matrícula a cada ${fmtNumero(eficiencia,1)} visitas`:'sem matrícula no período'}</small></div>
     <div class="director-kpi"><strong>${fmtNumero(conversaoMeta,1)}%</strong><span>taxa de conversão</span><small>matrículas ÷ visitas × 100</small></div>
     <div class="director-kpi"><strong>${fmtNumero(f.faltam)}</strong><span>gap final da meta</span><small>matrículas que ainda faltam</small></div>
     <div class="director-kpi"><strong>${fmtNumero(ritmoAtual,1)} vs ${fmtNumero(ritmoIdeal,1)}</strong><span>média real vs média ideal / dia</span><small>${ritmoLabel}</small></div>
     <div class="director-kpi"><strong>${f.visitasDiaRitmoIdeal==null?'—':fmtNumero(f.visitasDiaRitmoIdeal,1)}</strong><span>visitas / dia para o ritmo ideal</span><small>${eficiencia?`usando a eficiência atual de ${fmtNumero(eficiencia,1)} / 1`:'aguardando conversão'}</small></div>
     <div class="director-kpi"><strong>${f.visitasExtrasDia==null?'—':'+'+fmtNumero(f.visitasExtrasDia,1)}</strong><span>visitas extras / dia para recuperar</span><small>ritmo de recuperação: ${fmtNumero(ritmoRecuperacao,1)} matrícula(s)/dia</small></div>
   </div>
   <div class="card strategy-card"><b>🎯 O que precisa melhorar para chegar à meta?</b><div class="strategy-grid">
     <div class="strategy-mini"><strong>${fmtNumero(ritmoIdeal,1)}</strong><span>média ideal de matrículas por dia comercial</span></div>
     <div class="strategy-mini"><strong>${fmtNumero(ritmoRecuperacao,1)}</strong><span>matrículas/dia necessárias daqui pra frente para fechar o gap</span></div>
     <div class="strategy-mini"><strong>${eficiencia?fmtNumero(eficiencia,1)+' / 1':'—'}</strong><span>eficiência atual: visitas por matrícula</span></div>
     <div class="strategy-mini"><strong>${f.visitasDiaRitmoIdeal==null?'—':fmtNumero(f.visitasDiaRitmoIdeal,1)}</strong><span>visitas/dia para sustentar a média ideal</span></div>
     <div class="strategy-mini"><strong>${f.visitasDiaRecuperacao==null?'—':fmtNumero(f.visitasDiaRecuperacao,1)}</strong><span>visitas/dia para recuperar e fechar a meta no prazo</span></div>
     <div class="strategy-mini"><strong>${f.visitasExtrasDia==null?'—':'+'+fmtNumero(f.visitasExtrasDia,1)}</strong><span>visitas extras/dia sobre a média atual de ${fmtNumero(f.mediaVisitasDia??0,1)}</span></div>
   </div><div class="strategy-copy">${esc(f.orientacaoMeta||'')}</div></div>`;
 }else{
   directorPerformance.classList.add('hide');directorPerformance.innerHTML='';
 }
 if(!top){leaderSpotlight.innerHTML='<div class="card rank-empty">Ainda não há resultado neste período.</div>';ranking.innerHTML='';return}
 leaderSpotlight.innerHTML=`<div id="leaderCard" class="leader-card ${animar?'animate':''}" onclick="openProfile(${Number(top.id)})" style="cursor:pointer"><div class="leader-crown">👑</div>${leaderPhotoHtml(top)}<div class="leader-name">${esc(top.nome)} ${badgeMini(top.id)}</div><div class="leader-stats">${fmtNumero(top.atendimentos)} atendimentos • ${fmtNumero(top.conversao,1)}% conversão</div><div class="leader-score">${fmtNumero(top.matriculas)} matrícula${Number(top.matriculas)===1?'':'s'}</div></div>`;
 const resto=lista.slice(1);
 ranking.innerHTML=resto.length?`<div class="rank-list-title">Classificação</div>`+resto.map((r,i)=>`<div class="card rank with-photo"><div class="pos">${i+2}º</div>${photoHtml(r.nome,r.foto,'rank-photo')}<div><strong class="profile-link" onclick="openProfile(${Number(r.id)})">${esc(r.nome)}</strong>${badgeMini(r.id)}<small>${r.atendimentos} atendimentos • ${r.conversao}% conversão</small></div><b>${r.matriculas}</b></div>`).join(''):'';
}
function abrirPerformance(){rankingPeriodoAtual='dia';document.querySelectorAll('#rankingPeriodSwitch button').forEach(b=>b.classList.toggle('on',b.dataset.p==='dia'));renderPerformance(true)}
let BET_TARGET=null;
function canBet(){return !!S && (S.user.perfil!=='vendedor' || S.user.perfil==='financeiro');}
function renderBetPanel(){const box=document.getElementById('betPanel');if(!box)return;if(!canBet()){box.classList.add('hide');box.innerHTML='';return}box.classList.remove('hide');const aps=S.apostas||[];const saldo=Number(S.saldoFichas||0);box.innerHTML=`<div class="sectiontitle">🎰 Fichas da Arena</div><div class="bet-panel"><div class="bet-head"><div><b>Apostas de confiança</b><div style="font-size:.61rem;color:#71869a;margin-top:3px">Diretoria, Gestão e Financeiro apoiam um vendedor com fichas virtuais.</div></div><span class="bet-balance">${saldo}/100 fichas</span></div>${aps.length?aps.map(a=>`<div class="bet-row"><div><b>${esc(a.apostador_nome)}</b> → ${esc(a.vendedor_nome)}<br><span style="color:#7e91a5">${Number(a.fichas)} fichas • ${a.tipo==='hat_trick'?'Hat-trick':a.tipo==='duas_matriculas'?'2 matrículas':'Próxima matrícula'}</span></div><span class="bet-status ${esc(a.status)}">${a.status==='ganhou'?'GANHOU 🏆':a.status==='perdeu'?'ENCERRADA':'ATIVA'}</span></div>`).join(''):'<div style="font-size:.66rem;color:#7e91a5;margin-top:10px">Ninguém colocou fichas em jogo hoje ainda.</div>'}</div>`;}
function openBet(vendedorId,nome){if(!canBet())return;BET_TARGET={id:Number(vendedorId),nome};document.getElementById('betTarget').textContent='Apostando em '+nome;const saldo=Number(S.saldoFichas||0);const inp=document.getElementById('betChips');inp.max=String(Math.max(1,saldo));inp.value=String(Math.min(25,Math.max(1,saldo)));document.getElementById('betSaldoInfo').textContent=`Você tem ${saldo} ficha(s) disponível(is) hoje. Para jogar tudo, coloque ${saldo}.`;document.getElementById('betModal').classList.add('on');}
function closeBetModal(){document.getElementById('betModal')?.classList.remove('on');BET_TARGET=null;}
async function saveBet(){if(!BET_TARGET)return;const fichas=Number(document.getElementById('betChips').value||0),tipo=document.getElementById('betType').value;if(fichas<1){alert('Informe quantas fichas deseja apostar.');return}try{await api('arena_apostar','POST',{vendedor_id:BET_TARGET.id,tipo,fichas});closeBetModal();await load(true);}catch(e){alert(e.message)}}
function openMyProfile(){if(S?.user?.vendedor_id)openProfile(Number(S.user.vendedor_id));}
function rpgLevel(r){const xp=Math.max(0,Number(r?.matriculas||0)*120+Number(r?.atendimentos||0)*8);const level=Math.max(1,Math.floor(xp/500)+1);return {xp,level,pct:Math.min(100,((xp%500)/500)*100)}}
function rpgClass(r){const m=Number(r?.matriculas||0),c=Number(r?.conversao||0);if(m>=5)return ['⚔️','Fechador'];if(c>=35)return ['🧠','Estrategista'];if(Number(r?.atendimentos||0)>=10)return ['⚡','Caçador'];return ['🛡️','Recruta']}
function rpgAvatar(r,small=false){if(r?.foto)return `<div class="rpg-avatar"><img src="${esc(r.foto)}" alt="${esc(r.nome)}"></div>`;const cl=rpgClass(r);return `<div class="rpg-avatar">${cl[0]}</div>`}
function renderArenaRpg(){const box=document.getElementById('arenaRpg');if(!box||!S)return;const lista=(S.periodos?.dia?.ranking||S.ranking||[]).slice(0,3);const matDia=Number(S.periodos?.dia?.matriculas||0);const bossMeta=10,bossRest=Math.max(0,bossMeta-matDia),bossPct=Math.min(100,(matDia/bossMeta)*100);const heroes=lista.length?lista.map(r=>{const lv=rpgLevel(r),cl=rpgClass(r);return `<div class="rpg-hero" onclick="openProfile(${Number(r.id)})" style="cursor:pointer"><span class="rpg-level">LV ${lv.level}</span>${rpgAvatar(r)}<strong>${esc(r.nome)}</strong><small>${cl[1]} • ${Number(r.matriculas||0)} venda(s)</small><div class="rpg-xp"><i style="width:${lv.pct}%"></i></div></div>`}).join(''):'<div style="grid-column:1/-1;font-size:.65rem;color:#c8dcef">Os personagens aparecem assim que o time registrar resultados hoje.</div>';const duelo=(S.desafios||[]).find(d=>d.status==='aceito');let duelHtml='';if(duelo){const a=(S.ranking||[]).find(r=>Number(r.id)===Number(duelo.desafiante_vendedor_id))||{nome:duelo.desafiante_nome},b=(S.ranking||[]).find(r=>Number(r.id)===Number(duelo.desafiado_vendedor_id))||{nome:duelo.desafiado_nome};const alvo=duelo.tipo==='tres_primeiro'?3:duelo.tipo==='proxima_matricula'?1:Math.max(3,Number(duelo.placar_desafiante||0),Number(duelo.placar_desafiado||0));const hpA=Math.max(0,100-(Number(duelo.placar_desafiado||0)/alvo)*100),hpB=Math.max(0,100-(Number(duelo.placar_desafiante||0)/alvo)*100);duelHtml=`<div class="rpg-duel"><div class="rpg-fighter">${rpgAvatar(a)}<b>${esc(a.nome)}</b><div class="rpg-hp"><i style="width:${hpA}%"></i></div></div><div class="rpg-vs">VS</div><div class="rpg-fighter">${rpgAvatar(b)}<b>${esc(b.nome)}</b><div class="rpg-hp enemy"><i style="width:${hpB}%"></i></div></div></div><div class="rpg-caption">Cada resultado do desafio ataca a barra do adversário. É apenas a representação visual do desafio comercial.</div>`}box.innerHTML=`<div class="rpg-shell"><div class="rpg-head"><b>⚡ Esquadrão do dia</b><span>PROTÓTIPO RPG</span></div><div class="rpg-party">${heroes}</div><div class="boss-card"><div class="boss-top"><span class="boss-icon">👹</span><div><b>BOSS DA EQUIPE • O GUARDIÃO DA META</b><small>O time inteiro ataca junto. Cada matrícula de hoje causa 1 golpe.</small></div></div><div class="boss-hp"><i style="width:${100-bossPct}%"></i></div><div class="boss-foot"><span>${bossRest?`${bossRest} golpe(s) para derrotar`:'BOSS DERROTADO 🏆'}</span><b>${Math.max(0,bossMeta-matDia)}/${bossMeta} HP</b></div></div>${duelHtml}</div>`}
function render(){who.textContent=S.user.nome+' • '+(Number(S.user.is_master)===1?'Diretor Master':S.user.perfil==='financeiro'?'Financeiro':S.user.perfil);ag.textContent=S.live.agendamentos;vis.textContent=S.live.visitasHoje;const pd=S.periodos?.dia||{};mat.textContent=Number(pd.matriculas||0);renderBetPanel();renderArenaRpg();
const challenges=S.desafios||[];
challengeList.innerHTML=challenges.length?challenges.map(d=>{const encerrado=d.status==='encerrado', vencedor=Number(d.vencedor_vendedor_id||0), nomeVencedor=vencedor===Number(d.desafiante_vendedor_id)?d.desafiante_nome:d.desafiado_nome;const statusClass=encerrado?'accepted':(d.status==='aceito'?'accepted':'waiting');const statusText=encerrado?'ENCERRADO 🏆':(d.status==='aceito'?'ACEITO 🔥':'AGUARDANDO ACEITE');const labelPlacar=d.tipo==='proxima_matricula'?'DESDE O ACEITE':(d.tipo==='tres_primeiro'?'CORRIDA ATÉ 3':'PLACAR HOJE');return `<article class="challenge"><div class="challenge-war"><div class="war-shield" aria-hidden="true"><i class="fa-solid fa-shield-halved shield-base"></i><span class="shield-swords">⚔️</span></div><div><div class="challenge-head"><div class="challenge-vs">${esc(d.desafiante_nome)} x ${esc(d.desafiado_nome)}</div><span class="challenge-status ${statusClass}">${statusText}</span></div><div class="challenge-title">${esc(d.titulo)}</div></div></div><div class="challenge-score"><div><strong>${Number(d.placar_desafiante||0)}</strong><span>${esc(d.desafiante_nome)}</span></div><div class="versus">${labelPlacar}</div><div><strong>${Number(d.placar_desafiado||0)}</strong><span>${esc(d.desafiado_nome)}</span></div></div>${encerrado?`<div class="challenge-title" style="margin-top:10px;color:#15803d;font-weight:950">🏆 ${esc(nomeVencedor)} venceu o desafio!</div>`:''}${d.status==='pendente'&&Number(S.user.vendedor_id)===Number(d.desafiante_vendedor_id)?`<div class="challenge-title" style="margin-top:8px">⏳ Esperando ${esc(d.desafiado_nome)} aceitar ou recusar.</div>`:''}${S.user.perfil==='vendedor' && Number(S.user.vendedor_id)===Number(d.desafiado_vendedor_id) && d.status==='pendente'?`<div class="challenge-actions"><button class="accept" onclick="respondChallenge(${d.id},'aceitar')">Aceitar desafio 🔥</button><button class="decline" onclick="respondChallenge(${d.id},'recusar')">Recusar</button></div>`:''}</article>`}).join(''):'<div class="card">Nenhum desafio lançado hoje.</div>';
renderFeed();
let f=S.funil;meta.value=f.meta;dias.value=f.diasMeta;if(metaInicio)metaInicio.value=f.metaInicio||'';if(metaCalendarInfo)metaCalendarInfo.textContent=`📅 ${f.diasDecorridos||0} dia(s) comercial(is) decorrido(s) • ${f.diasRestantes||0} restante(s) • fim previsto: ${f.metaFimBr||'—'}`;renderPerformance(false);
teamList.innerHTML=S.ranking.map(r=>`<div class="card rank with-photo"><div class="pos">👤</div><div onclick="openProfile(${Number(r.id)})" style="cursor:pointer">${photoHtml(r.nome,r.foto,'rank-photo')}</div><div><strong class="profile-link" onclick="openProfile(${Number(r.id)})">${esc(r.nome)}</strong>${badgeMini(r.id)}<small>${r.matriculas} matrículas • ${r.atendimentos} atendimentos</small></div><div style="display:flex;gap:5px;flex-wrap:wrap;justify-content:flex-end"><button class="poke" onclick="poke(${r.id})">Cutucar</button>${canBet()?`<button class="bet-btn" onclick="openBet(${r.id},'${esc(r.nome)}')">🎰 Apostar</button>`:''}${S.user.perfil==='vendedor' && Number(S.user.vendedor_id)!==Number(r.id)?`<button class="challenge-btn" onclick="challenge(${r.id},'${esc(r.nome)}')">⚔️ Desafiar</button>`:''}</div></div>`).join('');
uvend.innerHTML='<option value="">Sem vínculo com vendedor</option>'+S.ranking.map(r=>`<option value="${r.id}">${esc(r.nome)}</option>`).join('');
