const navCA=document.getElementById('navConfigAttendance');if(navCA){if(S.user.perfil==='vendedor'){navCA.dataset.v='attend';navCA.innerHTML='<i class="fa-solid fa-headset"></i>Atendimentos'}else if(S.user.perfil==='financeiro'){navCA.dataset.v='mine';navCA.innerHTML='<i class="fa-solid fa-file-circle-check"></i>Contratos'}else{navCA.dataset.v='config';navCA.innerHTML='<i class="fa-solid fa-gear"></i>Config'}};document.querySelectorAll('.nav button[data-v="performance"],.nav button[data-v="team"]').forEach(b=>b.classList.toggle('hide',S.user.perfil==='financeiro'));const mineMain=[...document.querySelectorAll('.nav button')].find(b=>b!==navCA&&b.dataset.v==='mine');if(mineMain)mineMain.classList.toggle('hide',S.user.perfil==='financeiro');
}


let ARENA_NOTIFS=[];
function notifReadKey(){return `arena_notifs_lidas_${Number(S?.user?.id||0)}`}
function getReadNotifs(){try{return new Set(JSON.parse(localStorage.getItem(notifReadKey())||'[]'))}catch(e){return new Set()}}
function saveReadNotifs(set){try{localStorage.setItem(notifReadKey(),JSON.stringify([...set].slice(-250)))}catch(e){}}
function notifIcon(tipo){return {reacao:'❤️',cutucada:'👉',desafio:'⚔️',contrato:'📄',matricula:'🏆'}[tipo]||'🔔'}
function fmtNotifDate(v){if(!v)return '';let t=String(v).trim();if(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(t))t=t.replace(' ','T')+'Z';const d=new Date(t);return Number.isNaN(d.getTime())?String(v):d.toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}
function renderNotifications(){const list=document.getElementById('notifList'),badge=document.getElementById('notifBadge');if(!list||!badge)return;const read=getReadNotifs();const unread=ARENA_NOTIFS.filter(n=>!read.has(n.key)).length;badge.textContent=unread>99?'99+':String(unread);badge.classList.toggle('on',unread>0);list.className='';list.innerHTML=ARENA_NOTIFS.length?ARENA_NOTIFS.map(n=>`<button type="button" class="notif-item ${read.has(n.key)?'':'unread'}" onclick="openNotification('${esc(n.key)}','${esc(n.secao||'timeline')}')"><span class="notif-ico">${notifIcon(n.tipo)}</span><span class="notif-copy"><b>${esc(n.titulo)}</b><p>${esc(n.texto||'')}</p><small>${esc(fmtNotifDate(n.criadoEm))}</small></span></button>`).join(''):'<div class="notif-empty">Nenhuma atualização nova para você.</div>'}
async function loadNotifications(){try{const r=await api('arena_notificacoes');ARENA_NOTIFS=Array.isArray(r.notificacoes)?r.notificacoes:[];renderNotifications()}catch(e){console.warn('Notificações',e)}}
function toggleNotifications(ev){ev?.stopPropagation();const menu=document.getElementById('notifMenu');if(!menu)return;const abrir=!menu.classList.contains('on');menu.classList.toggle('on',abrir);if(abrir){const read=getReadNotifs();ARENA_NOTIFS.forEach(n=>read.add(n.key));saveReadNotifs(read);setTimeout(renderNotifications,80)}}
function openNotification(key,secao){const read=getReadNotifs();read.add(key);saveReadNotifs(read);document.getElementById('notifMenu')?.classList.remove('on');const btn=[...document.querySelectorAll('.nav button')].find(b=>b.dataset.v===secao);if(btn)btn.click();renderNotifications()}
document.addEventListener('click',e=>{if(!e.target.closest('.arena-notifs'))document.getElementById('notifMenu')?.classList.remove('on')});

const tutorialSteps=[
 ['Bem-vindo à Arena ⚡','Aqui você acompanha o movimento comercial em tempo real, interage com o time e enxerga seu próprio desempenho.'],
 ['Timeline ao vivo','Atendimentos, matrículas, desafios e cutucadas aparecem aqui. A Arena atualiza automaticamente.'],
 ['Meu Painel','Esta é sua área individual: atendimentos, matrículas, conversão e seus contratos com pendências ficam reunidos aqui.'],
 ['Contratos e pendências','Quando a Qualidade marcar um contrato como pendente ou correção, você verá o motivo e o que falta para resolver.'],
 ['Desafios e equipe','Use a Arena para competir de forma saudável, acompanhar o ranking e manter o ritmo comercial.']
];let tutorialIndex=0;
function showTutorial(){if(localStorage.getItem('arenaTutorialV1')==='ok')return;tutorialIndex=0;renderTutorial();tutorial.classList.add('on')}
function renderTutorial(){const x=tutorialSteps[tutorialIndex];tutorialStep.textContent=`PASSO ${tutorialIndex+1} DE ${tutorialSteps.length}`;tutorialTitle.textContent=x[0];tutorialText.textContent=x[1];document.querySelector('.tutorial-next').textContent=tutorialIndex===tutorialSteps.length-1?'Começar':'Próximo'}
function nextTutorial(){if(tutorialIndex<tutorialSteps.length-1){tutorialIndex++;renderTutorial()}else finishTutorial()}
function finishTutorial(){localStorage.setItem('arenaTutorialV1','ok');tutorial.classList.remove('on')}
function statusLabel(s){return {nao_revisado:'Aguardando revisão',pendente:'Pendente',correcao:'Correção necessária',aprovado:'Aprovado'}[s]||s}
function brl(v){return Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}
function myNum(v,d=1){const n=Number(v);return Number.isFinite(n)?n.toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d}):'—'}
function checklistLabel(k){return {dados_contrato:'Dados, cursos, plano, parcelas e valores conferidos',assinaturas:'Contrato e promissória assinados',documentos_pessoais:'Documentos pessoais anexados',comprovante_residencia:'Comprovante de residência anexado',pagamento_anexado:'Forma / comprovante de pagamento anexado'}[k]||k}
function financeStatusLabel(v){return v==='aprovado'?'Validado':v==='correcao'?'Correção necessária':'Aguardando validação'}
function commissionStatusLabel(v){return {a_receber:'A receber',aguardando_primeira_mensalidade:'Aguardando 1ª mensalidade',pendencia_checklist:'Bloqueada por pendência',fora_regra_11:'Fora da regra das 11 vendas'}[v]||'Em acompanhamento'}
function openPendingWhatsApp(id){const c=findContractById(id);if(!c)return;let phone=String(c.telefone||'').replace(/\D/g,'');if(phone.length===10||phone.length===11)phone='55'+phone;if(!phone){alert('Este cadastro não possui WhatsApp/telefone informado.');return}const chk=c.checklist||{},faltas=[];if(!chk.dados_contrato)faltas.push('conferência dos dados do contrato');if(!chk.assinaturas)faltas.push('contrato/promissória assinados');if(!chk.documentos_pessoais)faltas.push('documentos pessoais');if(!chk.comprovante_residencia)faltas.push('comprovante de residência');if(!chk.pagamento_anexado)faltas.push('comprovante de pagamento');if(c.financeiroStatus==='correcao'&&c.financeiroObservacoes)faltas.push(c.financeiroObservacoes);if(!faltas.length){alert('Não há documento pendente identificado para solicitar.');return}const nome=String(c.nome||'').trim().split(/\s+/)[0]||'tudo bem';const itens=faltas.map((x,i)=>`${i+1}. ${x}`).join('\n');const msg=`Olá, ${nome}! Tudo bem? Aqui é do Liceu Brasil. Para concluirmos a documentação da sua matrícula, precisamos dos seguintes itens:\n\n${itens}\n\nPode nos enviar por aqui, por favor? Assim que recebermos, daremos continuidade à regularização do seu contrato. Obrigado!`;window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank','noopener');}
function contractCardHtml(cn,showSeller=false){const fin=cn.financeiroStatus||'pendente';return `<div class="card contract clickable ${esc(cn.status)}" onclick="openContractDetail(${Number(cn.visitaId)})"><div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start"><div><b>${esc(cn.nome)}</b>${showSeller?`<div class="obs"><strong>Vendedor:</strong> ${esc(cn.vendedor||'Sem vendedor')}</div>`:''}</div><div style="display:flex;gap:5px;flex-wrap:wrap;justify-content:flex-end"><span class="status">${esc(statusLabel(cn.status))}</span><span class="finance-badge ${esc(fin)}">💼 ${esc(financeStatusLabel(fin))}</span></div></div><div class="obs">${esc(cn.data)}${cn.protocolo?' • Protocolo '+esc(cn.protocolo):''} • ${cn.contratos} contrato(s)</div>${cn.alocacoesPendentes?`<div class="obs">🎓 ${cn.alocacoesPendentes} matrícula(s) aguardando alocação em turma</div>`:''}${cn.observacoes?`<div class="obs"><b>Orientação da Qualidade:</b> ${esc(cn.observacoes)}</div>`:''}${cn.financeiroObservacoes?`<div class="obs"><b>Financeiro:</b> ${esc(cn.financeiroObservacoes)}</div>`:''}${cn.documentosPendentes?`<div class="obs">⚠️ ${cn.documentosPendentes} item(ns) do checklist pendente(s)</div>`:''}${cn.taxasPendentes?`<div class="obs">💳 ${cn.taxasPendentes} taxa(s) pendente(s)${cn.taxaAtrasada?' • <b style="color:#b42318">ATRASADA</b>':''}</div>`:''}${cn.primeiraMensalidadeStatus?`<div class="obs">💰 1ª mensalidade: <b>${cn.primeiraMensalidadeStatus==='pago'?'PAGA'+(cn.primeiraMensalidadePagoEm?' em '+cn.primeiraMensalidadePagoEm:''):cn.primeiraMensalidadeStatus==='nao_pago'?'NÃO PAGA':'AGUARDANDO'}</b></div>`:''}${cn.statusComissao?`<div class="obs"><b>Comissão:</b> ${esc(commissionStatusLabel(cn.statusComissao))}${cn.pagamentoPrevisto?' • previsão '+esc(cn.pagamentoPrevisto):''}</div>`:''}<div class="obs" style="color:#075cae;font-weight:850">Clique para ver o que falta →</div></div>`}
