 <div class="sectiontitle">📄 Meus contratos</div>
 ${cs.length?cs.map(c=>contractCardHtml(c,false)).join(''):'<div class="card">Nenhum contrato encontrado para você.</div>'}`
}
function findContractById(id){return (MY?.contratos||[]).find(c=>Number(c.visitaId)===Number(id))||null}
function openContractDetail(id){const c=findContractById(id);if(!c)return;const modal=document.getElementById('contractDetailModal');document.getElementById('contractDetailTitle').textContent=c.nome||'Contrato';document.getElementById('contractDetailMeta').textContent=`Visita #${c.visitaId}${c.protocolo?' • Protocolo '+c.protocolo:''}${c.vendedor?' • Vendedor: '+c.vendedor:''}`;const chk=c.checklist||{};const keys=['dados_contrato','assinaturas','documentos_pessoais','comprovante_residencia','pagamento_anexado'];let html=`<div class="sectiontitle">O que está faltando</div><div class="pending-list">${keys.map(k=>`<div class="pending-row ${chk[k]?'ok':'bad'}"><span>${chk[k]?'✅':'⚠️'}</span><span>${esc(checklistLabel(k))}</span></div>`).join('')}</div>`;html+=`<div class="sectiontitle">Situação financeira</div><div class="pending-row ${(c.financeiroStatus==='aprovado')?'ok':'bad'}"><span>${c.financeiroStatus==='aprovado'?'✅':'💼'}</span><span><b>${esc(financeStatusLabel(c.financeiroStatus||'pendente'))}</b>${c.financeiroObservacoes?'<br>'+esc(c.financeiroObservacoes):''}</span></div>`;if(c.observacoes)html+=`<div class="sectiontitle">Observações da Qualidade</div><div class="card" style="margin:0;font-size:.72rem">${esc(c.observacoes)}</div>`;if(c.taxasPendentes)html+=`<div class="sectiontitle">Taxa de matrícula</div><div class="pending-row bad">💳 ${Number(c.taxasPendentes)} taxa(s) pendente(s)${c.taxaAtrasada?' • ATRASADA':''}</div>`;html+=`<div class="sectiontitle">Acompanhamento da comissão</div><div class="pending-row ${c.statusComissao==='a_receber'?'ok':'bad'}"><span>💰</span><span><b>${esc(commissionStatusLabel(c.statusComissao))}</b><br>1ª mensalidade: ${c.primeiraMensalidadeStatus==='pago'?'paga'+(c.primeiraMensalidadePagoEm?' em '+esc(c.primeiraMensalidadePagoEm):''):c.primeiraMensalidadeStatus==='nao_pago'?'não paga':'aguardando'}${c.competenciaLiberacao?'<br>Competência: '+esc(c.competenciaLiberacao)+' • pagamento previsto: '+esc(c.pagamentoPrevisto||'—'):''}</span></div>`;if(S?.user?.perfil==='vendedor'&&c.telefone&&(c.faltasChecklist||[]).length){html+=`<div style="margin-top:12px"><button type="button" class="finance-save" onclick="openPendingWhatsApp(${Number(c.visitaId)})">📲 Solicitar pendência no WhatsApp</button></div>`}if(S?.user?.perfil==='financeiro'){html+=`<div class="finance-box"><label class="finance-check"><input id="financeContractOk" type="checkbox" ${c.financeiroStatus==='aprovado'?'checked':''}> Contrato correto no Sponte</label><textarea id="financeContractObs" maxlength="700" placeholder="Se não estiver correto, descreva exatamente o que precisa ser ajustado...">${esc(c.financeiroObservacoes||'')}</textarea><div class="finance-actions"><button class="finance-cancel" type="button" onclick="closeContractDetail()">Cancelar</button><button class="finance-save" type="button" onclick="saveFinanceValidation(${Number(c.visitaId)})">Salvar validação</button></div></div>`}document.getElementById('contractDetailBody').innerHTML=html;modal.classList.add('on')}
