let arenaLoadPromise=null;
async function load(force=false){
 if(arenaLoadPromise){
   if(force){try{await arenaLoadPromise}catch(_){} return load(false)}
   return arenaLoadPromise;
 }
 arenaLoadPromise=(async()=>{try{S=await api('arena_dashboard');render();if(S.user.perfil==='vendedor'||S.user.perfil==='financeiro'||Number(S.user.is_master)===1)await loadMine();loadNotifications();showTutorial();if(arenaInitialLoad){arenaInitialLoad=false;stopArenaLoading()}}catch(e){console.error(e);document.getElementById('who').textContent='Erro ao carregar';document.getElementById('feed').innerHTML='<div class="card" style="color:#b42318"><b>Não foi possível carregar a Arena.</b><br>'+esc(e.message||'Erro desconhecido')+'</div>';if(arenaInitialLoad){const txt=document.getElementById('arenaLoadingText');if(txt)txt.textContent='Não foi possível concluir o carregamento: '+(e.message||'erro');setTimeout(()=>document.getElementById('arenaLoading')?.classList.add('off'),1800);arenaInitialLoad=false}throw e}})();
 try{return await arenaLoadPromise}finally{arenaLoadPromise=null}
}
async function react(id,tipo){
 const key=`${id}:${tipo}`;if(reactionPending.has(key))return;
 const e=(S?.timeline||[]).find(x=>Number(x.id)===Number(id));if(!e)return;
 reactionPending.add(key);
 let rd=(e.reacoes||[]).find(x=>x.reacao===tipo);
 if(!rd){rd={reacao:tipo,qtd:0,meu:0,nomes:[]};e.reacoes=e.reacoes||[];e.reacoes.push(rd)}
 const meuNome=String(S?.user?.nome||'Você');
 const antes={qtd:Number(rd.qtd||0),meu:Number(rd.meu||0),nomes:[...(rd.nomes||[])]};
 if(Number(rd.meu)===1){rd.meu=0;rd.qtd=Math.max(0,Number(rd.qtd||0)-1);rd.nomes=(rd.nomes||[]).filter(n=>n!==meuNome)}
 else{rd.meu=1;rd.qtd=Number(rd.qtd||0)+1;if(!(rd.nomes||[]).includes(meuNome))rd.nomes=[...(rd.nomes||[]),meuNome]}
 renderFeed();
 try{
   const resp=await api('arena_reagir','POST',{evento_id:id,reacao:tipo});
   const novo=resp.reacao||{};
   rd.qtd=Number(novo.qtd||0);rd.meu=Number(novo.meu||0);rd.nomes=Array.isArray(novo.nomes)?novo.nomes:[];
 }catch(err){
   rd.qtd=antes.qtd;rd.meu=antes.meu;rd.nomes=antes.nomes;
   alert(err.message);
 }finally{
   reactionPending.delete(key);renderFeed();
 }
}
