async function addComment(eventId){eventId=Number(eventId);const el=document.getElementById(`comment-${eventId}`);const texto=(el?.value||'').trim();if(!texto||commentPending.has(eventId))return;commentPending.add(eventId);renderFeed();try{await api('arena_comentar','POST',{evento_id:eventId,texto});const atual=document.getElementById(`comment-${eventId}`);if(atual)atual.value='';commentPending.delete(eventId);await load(true)}catch(e){commentPending.delete(eventId);renderFeed();alert(e.message)}}
