function renderProfile(p){const shell=document.getElementById('profileShell');const b=p.brasao||{};const foto=p.foto?`<div class="profile-photo"><img src="${esc(p.foto)}" alt="${esc(p.nome)}"></div>`:`<div class="profile-photo">${esc(initials(p.nome))}</div>`;const conquistas=p.conquistas||[];shell.innerHTML=`<div class="profile-cover"><button class="profile-close" type="button" onclick="closeProfile()">×</button>${foto}<h2>${esc(p.nome)}</h2><p>${p.usuario?'@'+esc(p.usuario.usuario)+' • '+esc(p.usuario.perfil):'Perfil comercial'}</p><div class="crest ${esc(b.classe||'bronze')}"><div class="crest-inner"><i class="fa-solid ${esc(b.icone||'fa-shield-halved')}"></i><b>${esc(b.nivel||'Bronze')}</b><small>${esc(b.faixa||'')}</small></div></div><p>Brasão definido pelo progresso da meta individual</p></div><div class="profile-body"><div class="profile-kpis"><div class="profile-kpi"><strong>${Number(p.matriculas||0)}</strong><span>matrículas</span></div><div class="profile-kpi"><strong>${Number(p.visitas||0)}</strong><span>visitas</span></div><div class="profile-kpi"><strong>${Number(p.conversao||0).toFixed(1).replace('.',',')}%</strong><span>conversão</span></div><div class="profile-kpi"><strong>${p.posicao? p.posicao+'º':'—'}</strong><span>posição</span></div></div><div class="card" style="margin-top:9px"><b>🎯 Progresso da meta • ${Number(p.matriculas||0)}/${Number(p.meta||0)}</b><div class="profile-progress"><div style="width:${Math.min(100,Math.max(0,Number(p.progresso||0)))}%"></div></div><div style="font-size:.62rem;color:#71869a;margin-top:6px">${Number(p.progresso||0).toFixed(1).replace('.',',')}% concluído • ${Number(p.faltam||0)} matrícula(s) faltando</div></div><div class="profile-next">${b.proximo?`Faltam <b>${Number(b.falta||0).toFixed(1).replace('.',',')} pontos percentuais</b> para o brasão ${esc(b.proximo)}.`:'<b>Nível máximo alcançado.</b> Agora é manter a consistência 🔥'}</div><div class="sectiontitle">🏅 Conquistas</div><div class="achievement-grid">${conquistas.length?conquistas.map(c=>`<div class="achievement"><div class="emoji">${esc(c.icone)}</div><div><b>${esc(c.titulo)}</b><p>${esc(c.texto)}</p></div></div>`).join(''):'<div class="card">As primeiras conquistas aparecem conforme os resultados entram.</div>'}</div><div class="sectiontitle">📊 Histórico rápido</div><div class="card"><div class="grid"><div class="metric"><strong>${Number(p.desafiosVencidos||0)}</strong><span>desafios vencidos</span></div><div class="metric"><strong>${Number(p.matriculasHistoricas||0)}</strong><span>matrículas históricas</span></div></div></div></div>`}

async function poke(id){let opts=['Bora pra próxima 🔥','Quero essa venda! 👀','Tá chegando! 🚀','A diretoria tá de olho 😄','Boa! Mantém o ritmo 👊'];let msg=prompt('Cutucada:\\n\\n'+opts.map((x,i)=>(i+1)+' - '+x).join('\\n')+'\\n\\nDigite o número:');let n=parseInt(msg);if(n>=1&&n<=opts.length){await api('arena_cutucar','POST',{vendedor_id:id,mensagem:opts[n-1]});load()}}

async function challenge(vendedorId,nome){
  const tipos=[
    ['mais_matriculas','Quem faz mais matrículas hoje?'],
    ['proxima_matricula','Quem fecha a próxima matrícula primeiro?'],
    ['tres_primeiro','Quem chega a 3 matrículas primeiro?']
  ];
  const escolha=prompt(`Desafiar ${nome}:\n\n1 - ${tipos[0][1]}\n2 - ${tipos[1][1]}\n3 - ${tipos[2][1]}\n\nDigite 1, 2 ou 3:`);
  const n=parseInt(escolha,10);
  if(!(n>=1&&n<=3)) return;
  try{
    await api('arena_desafiar','POST',{vendedor_id:vendedorId,tipo:tipos[n-1][0]});
    alert(`${nome} foi desafiado! ⚔️`);
    load();
  }catch(e){alert(e.message)}
}
