let ARENA_USER_PHOTO_DATA=null;
function renderArenaUserPhotoPreview(){const box=document.getElementById('userPhotoPreview');if(!box)return;const nome=(document.getElementById('unome')?.value||'Usuário').trim();box.innerHTML=ARENA_USER_PHOTO_DATA?`<img src="${esc(ARENA_USER_PHOTO_DATA)}" alt="${esc(nome)}">`:esc(initials(nome)||'👤')}
async function prepareArenaUserPhoto(file){if(!file)return;if(!String(file.type||'').startsWith('image/')){alert('Escolha um arquivo de imagem.');return}if(file.size>6*1024*1024){alert('A imagem é muito grande. Escolha uma foto de até 6 MB.');return}try{const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=data});const max=520,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale));const cv=document.createElement('canvas');cv.width=w;cv.height=h;const ctx=cv.getContext('2d');ctx.drawImage(img,0,0,w,h);ARENA_USER_PHOTO_DATA=cv.toDataURL('image/jpeg',.82);renderArenaUserPhotoPreview()}catch(e){alert('Não foi possível preparar essa foto.')}}
function removeArenaUserPhoto(){ARENA_USER_PHOTO_DATA='';const f=document.getElementById('ufoto');if(f)f.value='';renderArenaUserPhotoPreview()}
