async function saveUser(){try{const editing=!!uid.value;await api('arena_usuarios','POST',userPayload());alert(editing?'Acesso atualizado.':'Acesso criado.');cancelEditUser();await loadUsers();await load()}catch(e){alert(e.message)}}
function cancelEditUser(){uid.value='';unome.value='';uuser.value='';upass.value='';uperfil.value='vendedor';uperfil.disabled=false;uvend.value='';uativo.checked=true;uativo.disabled=false;ARENA_USER_PHOTO_DATA=null;const uf=document.getElementById('ufoto');if(uf)uf.value='';renderArenaUserPhotoPreview();userFormTitle.textContent='Novo acesso da Arena';userSaveBtn.textContent='Criar acesso';userCancelBtn.classList.add('hide');passwordHint.textContent='Ao criar um acesso, informe uma senha com pelo menos 6 caracteres.'}
function editUser(id){const u=ARENA_USERS.find(x=>Number(x.id)===Number(id));if(!u)return;uid.value=u.id;unome.value=u.nome||'';uuser.value=u.usuario||'';upass.value='';uperfil.value=u.perfil||'vendedor';uperfil.disabled=Number(u.is_master)===1;uvend.value=u.vendedor_id??'';uativo.checked=Number(u.ativo)===1;uativo.disabled=Number(u.is_master)===1;ARENA_USER_PHOTO_DATA=u.foto||'';const uf=document.getElementById('ufoto');if(uf)uf.value='';renderArenaUserPhotoPreview();userFormTitle.textContent='Editar acesso';userSaveBtn.textContent='Salvar alterações';userCancelBtn.classList.remove('hide');passwordHint.textContent='Deixe a senha em branco para manter a senha atual. Preencha somente se quiser redefini-la.';document.getElementById('config').scrollIntoView({behavior:'smooth',block:'start'})}
function renderUsers(){const box=document.getElementById('userList');if(!box)return;box.innerHTML=ARENA_USERS.length?ARENA_USERS.map(u=>`<div class="admin-user"><div style="display:flex;gap:9px;align-items:center"><div class="comment-avatar">${u.foto?`<img src="${esc(u.foto)}" alt="${esc(u.nome)}">`:esc(initials(u.nome))}</div><div><strong><span class="status-dot ${Number(u.ativo)===1?'':'off'}"></span>${esc(u.nome)}${Number(u.is_master)===1?' 👑':''}</strong><small>@${esc(u.usuario)} • ${Number(u.is_master)===1?'Diretor Master':esc(u.perfil)}${u.vendedor_nome?' • '+esc(u.vendedor_nome):''}${Number(u.id)===Number(ARENA_CURRENT_USER_ID)?' • você':''}</small></div></div><div class="admin-user-actions"><button class="admin-edit" type="button" onclick="editUser(${Number(u.id)})"><i class="fa-solid fa-pen"></i> Editar</button></div></div>`).join(''):'<div class="card">Nenhum acesso cadastrado.</div>'}
async function loadUsers(){if(Number(S?.user?.is_master)!==1)return;try{const r=await api('arena_usuarios');ARENA_USERS=r.usuarios||[];ARENA_CURRENT_USER_ID=Number(r.currentUserId||0);renderUsers()}catch(e){document.getElementById('userList').innerHTML=`<div class="card" style="color:#b42318">${esc(e.message)}</div>`}}
async function addUser(){return saveUser()}
async function logout(){try{await api('arena_logout','POST',{});}catch(e){}location.href='arena-login.php'}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button,.view').forEach(x=>x.classList.remove('on'));b.classList.add('on');$('#'+b.dataset.v).classList.add('on');if(b.dataset.v==='performance')abrirPerformance();if(b.dataset.v==='mine')loadMine();if(b.dataset.v==='attend')loadAttendances();if(b.dataset.v==='config')loadUsers()});
document.getElementById('postText')?.addEventListener('input',e=>{document.getElementById('postCount').textContent=`${e.target.value.length}/280`});
document.getElementById('postText')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();publishPost()}});
document.getElementById('unome')?.addEventListener('input',()=>{if(!ARENA_USER_PHOTO_DATA)renderArenaUserPhotoPreview()});
document.getElementById('feed')?.addEventListener('keydown',e=>{const input=e.target.closest('input[id^="comment-"]');if(!input||e.key!=='Enter'||e.shiftKey)return;e.preventDefault();const id=Number(input.id.replace('comment-',''));if(id>0)addComment(id)});
renderArenaUserPhotoPreview();
load();setInterval(()=>load(false),10000);setInterval(loadNotifications,15000);
</script></body></html>